grid = ["##########","#...#...##","###.#.#..#","#.#.#.#.##","#.#.#..###","#.#.#...##","#.#.###.##","#.......##","####.#####","##########"]
dirs = {"U":(-1,0),"D":(1,0),"L":(0,-1),"R":(0,1)}
def step_p(col, dcol):
    ncol = col + dcol
    return (ncol, dcol) if 5 <= ncol <= 7 else (col - dcol, -dcol)
def mv(p, dr, dc):
    nr, nc = p[0]+dr, p[1]+dc
    return p if grid[nr][nc] == "#" else (nr, nc)

path = "RDDDDDLLLDLLRRRRRRUULUUUUL"
c, d, g, pc, pd = (1,2), (5,7), False, 5, 1
for i, m in enumerate(path, 1):
    dr, dc = dirs[m]
    nc, nd = mv(c, dr, dc), mv(d, dr, dc)
    assert nc != nd and not (nc == d and nd == c), f"piece collision at {i}"
    if nc != c and nc in [(7,1),(6,7)]: g = not g
    if g:
