    po = (5, pc)
    pc, pd = step_p(pc, pd)
    pn = (5, pc)
    assert nc != pn and nd != pn and not (nc == po and c == pn) and not (nd == po and d == pn), f"patrol collision at {i}: C={c}->{nc}, d={d}->{nd}, P={po}->{pn}"
    c, d = nc, nd
    print(f"{i:2d} {m}: C={c} d={d} g={g} P={pn}")
