dirs = [(-1,0,"U"), (1,0,"D"), (0,-1,"L"), (0,1,"R")]
def step_p(col, dcol):
    ncol = col + dcol
    return (ncol, dcol) if 5 <= ncol <= 7 else (col - dcol, -dcol)
def mv(p, dr, dc):
    nr, nc = p[0]+dr, p[1]+dc
    return p if grid[nr][nc] == "#" else (nr, nc)

init = ((1,2), (5,7), False, 5, 1)
q = deque([(init, [])]); seen = {init}
while q:
    (c, d, g, pc, pd), path = q.popleft()
    if (c, d) == ((4,5), (3,3)):
        print("len=", len(path), "".join(path))
        break
    npc, npd = step_p(pc, pd)
    po, pn = (5, pc), (5, npc)
    for dr, dc, nm in dirs:
        nc = mv(c, dr, dc)
        # require visiting (7,1) first so g=True when entering (6,7), and never staying on (7,1) or (6,7)
